package org.example;

import com.almasb.fxgl.app.GameApplication;
import com.almasb.fxgl.app.GameSettings;
import javafx.scene.input.KeyCode;
import org.example.config.GameConfig;
import org.example.screen.GameScreen;
import org.example.screen.MenuScreen;
import org.example.screen.PauseScreen;
import org.example.screen.SettingsScreen;
import org.example.state.GameState;

import static com.almasb.fxgl.dsl.FXGL.getGameController;
import static com.almasb.fxgl.dsl.FXGL.onKey;

public class EdGameApplication extends GameApplication {

    private GameState currentState;
    private MenuScreen menuScreen;
    private SettingsScreen settingsScreen;
    private PauseScreen pauseScreen;
    private GameScreen gameScreen;

    @Override
    protected void initSettings(GameSettings settings) {
        settings.setWidth(GameConfig.WINDOW_WIDTH);
        settings.setHeight(GameConfig.WINDOW_HEIGHT);
        settings.setTitle(GameConfig.WINDOW_TITLE);
        // Disable developer overlay
        settings.setDeveloperMenuEnabled(false);
    }

    @Override
    protected void initInput() {
        // Override FXGL's default ESC pause behavior with our custom pause screen
        onKey(KeyCode.ESCAPE, () -> {
            if (currentState == GameState.PLAYING) {
                currentState = GameState.PAUSED;
                showPauseScreen();
            }
        });
    }

    @Override
    protected void initGame() {
        currentState = GameState.MENU;
        showMenuScreen();
    }

    private void showMenuScreen() {
        menuScreen = new MenuScreen(
                this::startGame,          // onStartCallback
                this::exitGame,           // onExitCallback
                this::showSettingsScreen  // onSettingsCallback
        );
        menuScreen.init();
    }

    private void showSettingsScreen() {
        settingsScreen = new SettingsScreen(this::showMenuScreen);
        settingsScreen.init();
    }

    private void startGame() {
        if (menuScreen != null) {
            menuScreen.cleanup();
        }
        currentState = GameState.PLAYING;
        gameScreen = new GameScreen(this);
        gameScreen.init();
    }

    private void showPauseScreen() {
        pauseScreen = new PauseScreen(
                this::resumeGame,
                this::showOptionsFromPause,
                this::backToMenuFromPause,
                this::exitGame
        );
        pauseScreen.init();
    }

    private void resumeGame() {
        if (pauseScreen != null) {
            pauseScreen.cleanup();
        }
        currentState = GameState.PLAYING;
    }

    private void showOptionsFromPause() {
        // Options are now integrated into PauseScreen
        // This method can be removed or used for advanced options
    }

    private void backToMenuFromPause() {
        if (pauseScreen != null) {
            pauseScreen.cleanup();
        }
        if (gameScreen != null) {
            gameScreen.cleanup();
        }
        currentState = GameState.MENU;
        showMenuScreen();
    }

    private void exitGame() {
        getGameController().exit();
    }


    public GameState getCurrentState() {
        return currentState;
    }
}

package org.example;

import com.almasb.fxgl.app.GameApplication;
import com.almasb.fxgl.app.GameSettings;
import javafx.scene.input.KeyCode;
import org.example.config.GameConfig;
import org.example.screen.GameScreen;
import org.example.screen.MenuScreen;
import org.example.screen.PauseScreen;
import org.example.screen.SettingsScreen;
import org.example.state.GameState;

import static com.almasb.fxgl.dsl.FXGL.getGameController;
import static com.almasb.fxgl.dsl.FXGL.onKey;

public class EdGameApplication extends GameApplication {

    private GameState currentState;
    private MenuScreen menuScreen;
    private SettingsScreen settingsScreen;
    private PauseScreen pauseScreen;
    private GameScreen gameScreen;

    @Override
    protected void initSettings(GameSettings settings) {
        settings.setWidth(GameConfig.WINDOW_WIDTH);
        settings.setHeight(GameConfig.WINDOW_HEIGHT);
        settings.setTitle(GameConfig.WINDOW_TITLE);

        // Disable FXGL's built-in menus and pause
        settings.setDeveloperMenuEnabled(false);
        settings.setMainMenuEnabled(false);
        settings.setGameMenuEnabled(false);
    }

    @Override
    protected void initInput() {
        // Override FXGL's default ESC pause behavior with our custom pause screen
        onKey(KeyCode.ESCAPE, () -> {
            if (currentState == GameState.PLAYING) {
                currentState = GameState.PAUSED;
                showPauseScreen();
            }
        });
    }

    @Override
    protected void initGame() {
        currentState = GameState.MENU;
        showMenuScreen();
    }

    private void showMenuScreen() {
        menuScreen = new MenuScreen(
                this::startGame,          // onStartCallback
                this::exitGame,           // onExitCallback
                this::showSettingsScreen  // onSettingsCallback
        );
        menuScreen.init();
    }

    private void showSettingsScreen() {
        settingsScreen = new SettingsScreen(this::showMenuScreen);
        settingsScreen.init();
    }

    private void startGame() {
        if (menuScreen != null) {
            menuScreen.cleanup();
        }
        currentState = GameState.PLAYING;
        gameScreen = new GameScreen(this);
        gameScreen.init();
    }

    private void showPauseScreen() {
        pauseScreen = new PauseScreen(
                this::resumeGame,
                this::showOptionsFromPause,
                this::backToMenuFromPause,
                this::exitGame
        );
        pauseScreen.init();
    }

    private void resumeGame() {
        if (pauseScreen != null) {
            pauseScreen.cleanup();
        }
        currentState = GameState.PLAYING;
    }

    private void showOptionsFromPause() {
        // Options are now integrated into PauseScreen
        // This method can be removed or used for advanced options
    }

    private void backToMenuFromPause() {
        if (pauseScreen != null) {
            pauseScreen.cleanup();
        }
        if (gameScreen != null) {
            gameScreen.cleanup();
        }
        currentState = GameState.MENU;
        showMenuScreen();
    }

    private void exitGame() {
        getGameController().exit();
    }


    public GameState getCurrentState() {
        return currentState;
    }
}

package org.example.entity;

import com.almasb.fxgl.entity.Entity;
import javafx.scene.layout.StackPane;
import javafx.scene.paint.Color;
import javafx.scene.shape.Rectangle;
import org.example.config.GameConfig;
import org.example.entity.player.PlayerComponent;

import static com.almasb.fxgl.dsl.FXGL.entityBuilder;
import static com.almasb.fxgl.dsl.FXGL.texture;

public class EntityFactory {

    public static Entity createGround() {
        return entityBuilder()
                .at(0, GameConfig.GROUND_Y)
                .view(new Rectangle(GameConfig.WINDOW_WIDTH, GameConfig.GROUND_HEIGHT, Color.DARKGREEN))
                .buildAndAttach();
    }

    public static Entity createPlayer() {
        PlayerComponent playerComponent = new PlayerComponent();
        StackPane container = new StackPane();
        container.setPrefSize(GameConfig.PLAYER_SIZE, GameConfig.PLAYER_SIZE);
        container.getChildren().add(texture("player_idle1.png", GameConfig.PLAYER_SIZE, GameConfig.PLAYER_SIZE));
        playerComponent.setTextureContainer(container);

        return entityBuilder()
                .at(GameConfig.PLAYER_START_X, GameConfig.PLAYER_START_Y)
                .view(container)
                .with(playerComponent)
                .buildAndAttach();
    }

    public static PlayerComponent getPlayerComponent(Entity player) {
        return player.getComponent(PlayerComponent.class);
    }
}

package org.example.entity;

import com.almasb.fxgl.entity.Entity;
import com.almasb.fxgl.texture.Texture;
import javafx.scene.layout.Pane;
import javafx.scene.layout.StackPane;
import javafx.scene.paint.Color;
import javafx.scene.shape.Rectangle;
import org.example.config.GameConfig;
import org.example.entity.player.PlayerComponent;

import static com.almasb.fxgl.dsl.FXGL.entityBuilder;
import static com.almasb.fxgl.dsl.FXGL.texture;

public class EntityFactory {

    public static Entity createGround() {
        int cols = (int) Math.ceil((double) GameConfig.WINDOW_WIDTH / GameConfig.TILE_SIZE);
        int rows = (int) Math.ceil((double) GameConfig.GROUND_HEIGHT / GameConfig.TILE_SIZE);

        Pane groundView = new Pane();
        groundView.setPrefSize(cols * GameConfig.TILE_SIZE, rows * GameConfig.TILE_SIZE);

        for (int row = 0; row < rows; row++) {
            for (int col = 0; col < cols; col++) {
                String tileName = row == 0 ? "grass.png" : "dirt.png";
                Texture tile = texture(tileName, GameConfig.TILE_SIZE, GameConfig.TILE_SIZE);
                tile.setTranslateX(col * GameConfig.TILE_SIZE);
                tile.setTranslateY(row * GameConfig.TILE_SIZE);
                groundView.getChildren().add(tile);
            }
        }

        return entityBuilder()
                .at(0, GameConfig.GROUND_Y)
                .view(groundView)
                .buildAndAttach();
    }

    public static Entity createPlayer() {
        PlayerComponent playerComponent = new PlayerComponent();
        StackPane container = new StackPane();
        container.setPrefSize(GameConfig.PLAYER_SIZE, GameConfig.PLAYER_SIZE);
        container.getChildren().add(texture("sprites/player_idle1.png", GameConfig.PLAYER_SIZE, GameConfig.PLAYER_SIZE));
        playerComponent.setTextureContainer(container);

        return entityBuilder()
                .at(GameConfig.PLAYER_START_X, GameConfig.PLAYER_START_Y)
                .view(container)
                .with(playerComponent)
                .buildAndAttach();
    }

    public static PlayerComponent getPlayerComponent(Entity player) {
        return player.getComponent(PlayerComponent.class);
    }
}

package org.example.config;

public class GameConfig {
    // Window settings
    // Use 16:9 aspect ratio by default (e.g. 1280x720)
    public static final int WINDOW_WIDTH = 1280;
    public static final int WINDOW_HEIGHT = 720;
    public static final String WINDOW_TITLE = "EdGame";

    // Ground
    public static final int GROUND_Y = 500;
    public static final int GROUND_HEIGHT = 100;

    // Player
    public static final int PLAYER_SIZE = 40;
    public static final int PLAYER_START_X = 100;
    public static final int PLAYER_START_Y = 300;
    public static final double PLAYER_SPEED = 3;
    public static final double PLAYER_GRAVITY = 0.3;
    public static final double PLAYER_JUMP_STRENGTH = -12;
}

